using System;
using System.Globalization;
using System.IO;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Deletes the Chernarus mission's persistence folder (storage_<instanceId>), the same folder the Windows
// batch version removes. The server recreates it, with a fresh world state, on its next start.
string raw = ThisService.Variables?.Parse<string>("instanceId", "1") ?? "1";
int instanceId = double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out var parsed) && parsed >= 1
    ? (int)parsed
    : 1;

string storage = Path.Combine(ThisService.RootDirectory, "mpmissions", "dayzOffline.chernarusplus", $"storage_{instanceId}");
if (Directory.Exists(storage))
{
    Directory.Delete(storage, true);
    ScriptConsole.WriteLine($"Deleted {storage}.");
}
else
{
    ScriptConsole.WriteLine($"Nothing to delete: {storage} does not exist.");
}

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.GameHosting.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using Microsoft.EntityFrameworkCore;
using TCAdmin.Web.Shared.Models;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

string fileTitle = Convert.ToString(Globals.Dynamic.FileTitle) ?? string.Empty;
string fileId = Convert.ToString(Globals.Dynamic.FileId) ?? string.Empty;
string installPath = Convert.ToString(Globals.Dynamic.InstallPath) ?? string.Empty;
var tagsArray = Globals.Dynamic.TagsArray as IEnumerable<string>;

// Keep only the characters the mod folder name may contain, collapse double spaces, then use "_" as the
// word separator. Falls back to the file id when the provider gave us no title.
string modName = fileTitle.Length != 0
    ? Regex.Replace(fileTitle, @"[^a-zA-Z0-9 \]\[_'+-]", string.Empty)
        .Replace("  ", " ").Replace(" ", "_").Trim()
    : fileId;

// DayZ on Linux opens mod folders and files case-sensitively, with lowercase names (Windows doesn't care).
// Use a lowercase folder name there; the uninstall script must build the same name.
if (!System.OperatingSystem.IsWindows())
    modName = modName.ToLowerInvariant();

// Tags are only populated when the custom mod provider is configured to use the Steam API. No tags means
// no "Server" tag, so the mod is registered as a client mod - the same fallback the V2 script had.
bool isServer = tagsArray != null && tagsArray.Contains("Server");

// 1) Move the downloaded workshop folder to the "@ModName" location the game expects.
string modFolder = Path.Combine(ThisService.RootDirectory, $"@{modName}");
if (Directory.Exists(modFolder))
    Directory.Delete(modFolder, true);
Directory.Move(installPath, modFolder);

// On Linux, lowercase every file and folder inside the mod, deepest first so a parent rename never
// invalidates a child path still to be visited. A name differing only in case is renamed via a temporary
// name, since a case-only Move is a no-op on case-insensitive file systems.
if (!System.OperatingSystem.IsWindows())
{
    void Rename(string path, bool isDirectory)
    {
        string name = Path.GetFileName(path);
        string lower = name.ToLowerInvariant();
        if (name == lower)
            return;
        string target = Path.Combine(Path.GetDirectoryName(path)!, lower);
        if (isDirectory)
        {
            if (Directory.Exists(target))
            {
                // Merge into an existing lowercase folder of the same name.
                foreach (string child in Directory.GetFileSystemEntries(path))
                {
                    string dest = Path.Combine(target, Path.GetFileName(child));
                    if (Directory.Exists(child)) Directory.Move(child, dest);
                    else File.Move(child, dest, true);
                }
                Directory.Delete(path, true);
            }
            else
            {
                Directory.Move(path, target);
            }
        }
        else
        {
            File.Move(path, target, true);
        }
    }

    foreach (string file in Directory.GetFiles(modFolder, "*", SearchOption.AllDirectories))
        Rename(file, false);
    foreach (string dir in Directory.GetDirectories(modFolder, "*", SearchOption.AllDirectories)
                 .OrderByDescending(d => d.Length))
        Rename(dir, true);
}

// 2) Copy every key the mod ships (*.bikey, wherever it keeps them) into the service's root "keys" folder so
//    the server accepts the signed content.
string rootKeys = Path.Combine(ThisService.RootDirectory, "keys");
Directory.CreateDirectory(rootKeys);
foreach (string file in Directory.GetFiles(modFolder, "*.bikey", SearchOption.AllDirectories))
    File.Copy(file, Path.Combine(rootKeys, Path.GetFileName(file)), true);

// 3) Only once the files are in place, register the mod in the service's variables - a failed move must not
//    leave a mod listed that is not on disk. ThisService belongs to the task handler's DbContext, so load
//    the row tracked in THIS script's scope before editing it.
var service = await GameServiceManager.GetAsync(ThisService.ServiceId);
if (service == null)
{
    ScriptConsole.WriteLine($"[err] Service {ThisService.ServiceId} not found. '@{modName}' was installed but not registered.");
    return;
}

var currentVariables = service.Variables ?? new TCAdminVars();
string serverMods = currentVariables.Parse<string>("ServerMods", string.Empty) ?? string.Empty;
string mods = currentVariables.Parse<string>("Mods", string.Empty) ?? string.Empty;

var updatedVariables = new TCAdminVars();
foreach (var pair in currentVariables)
    updatedVariables[pair.Key] = pair.Value;

if (isServer)
    updatedVariables["ServerMods"] = $"@{modName};{serverMods}";
else
    updatedVariables["Mods"] = $"@{modName};{mods}";

// Service.Variables is a JSON column with no value comparer, so change tracking sees neither an in-place
// edit nor a reassignment - force the row Modified or the write is silently dropped.
service.Variables = updatedVariables;
GameServiceManager.TCAdminDbContext.Entry(service).State = EntityState.Modified;
await GameServiceManager.SaveChangesAsync(ThisCancellationToken);

// 4) The V2 equivalent of ThisService.Configure(): rebuild the parsed command line so the new mod reaches
//    the launch arguments. The monitor starts Service.Commandline verbatim with no re-parse, so without
//    this the mod is installed but never loaded.
var refresh = await ServiceManager.RefreshActiveCommandLine(null, service);
if (refresh.Error != null)
    ScriptConsole.WriteLine($"[warn] Command line refresh failed: {refresh.Error}");

ScriptConsole.WriteLine($"Installed '@{modName}' and added it to {(isServer ? "ServerMods" : "Mods")}.");

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.GameHosting.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll
using System;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.EntityFrameworkCore;
using TCAdmin.Web.Shared.Models;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Must produce exactly the same name the install script built, or the folder and the mod-list entry are
// both left behind.
string fileTitle = Convert.ToString(Dynamic.FileTitle) ?? string.Empty;
string modName;

if (fileTitle.Length != 0)
{
    var builder = new StringBuilder();
    foreach (char character in fileTitle)
    {
        builder.Append(Regex.IsMatch(character.ToString(), @"[a-zA-Z0-9 \]\[_\'+-]") ? character : '\0');
    }

    modName = builder.ToString().Replace("\0", string.Empty);
    modName = modName.Replace("  ", " ").Replace(" ", "_").Trim();
}
else
{
    modName = Convert.ToString(Dynamic.FileId) ?? string.Empty;
}

// The install script lowercases the folder name on Linux (DayZ there reads mod names case-sensitively).
if (!System.OperatingSystem.IsWindows())
{
    modName = modName.ToLowerInvariant();
}

// ThisService belongs to the task handler's scope, so load the row tracked in THIS script's scope.
var service = await GameServiceManager.GetAsync(ThisService.ServiceId);
if (service == null)
{
    ScriptConsole.WriteLine($"Service {ThisService.ServiceId} no longer exists.");
    return;
}

// Strip the entry from both lists - the tags that decided which one it went into are not reliably
// available at uninstall time.
var currentVariables = service.Variables ?? new TCAdminVars();
string serverMods = currentVariables.Parse<string>("ServerMods", string.Empty) ?? string.Empty;
string mods = currentVariables.Parse<string>("Mods", string.Empty) ?? string.Empty;

var updatedVariables = new TCAdminVars();
foreach (var pair in currentVariables)
{
    updatedVariables[pair.Key] = pair.Value;
}

updatedVariables["ServerMods"] = serverMods.Replace($"@{modName};", string.Empty);
updatedVariables["Mods"] = mods.Replace($"@{modName};", string.Empty);
service.Variables = updatedVariables;

// The uninstall handler already removed the files it tracked at install time; this clears anything the
// game itself wrote inside the mod folder afterwards.
string modFolder = Path.Combine(ThisService.RootDirectory, $"@{modName}");
if (Directory.Exists(modFolder))
{
    Directory.Delete(modFolder, true);
}

// Persist only once the folder is gone, the way V2's trailing ThisService.Save() did. Service.Variables is
// a JSON column with no value comparer, so the forced state is what makes the write happen at all.
GameServiceManager.TCAdminDbContext.Entry(service).State = EntityState.Modified;
await GameServiceManager.SaveChangesAsync(ThisCancellationToken);

// V2's ThisService.Configure(): rebuild the launch arguments so the removed mod stops being passed.
var refresh = await ServiceManager.RefreshActiveCommandLine(null, service);
if (refresh.Error != null)
{
    ScriptConsole.WriteLine($"[warn] Command line refresh failed: {refresh.Error}");
}

ScriptConsole.WriteLine($"Removed '@{modName}' from the service's mod list.");
